p=Path(__file__).resolve().parent;arch=platform.machine();r=Path('/tmp/xdiff/rustc.txt').read_text().strip();ld=Path('/tmp/xdiff/libdir.txt').read_text().strip()+':'+os.environ.get('LD_LIBRARY_PATH','');e=os.environ.copy();e['LD_LIBRARY_PATH']=ld;extra=json.loads((p/('fingerprint.'+arch+'.json')).read_text())['rustflags']+['-Cllvm-args=-two-entry-phi-node-folding-threshold=16'];c=[r,'--edition=2024','-O','-Ccodegen-units=1','--emit=link,asm,llvm-ir',*extra,str(p/'matrix.rs'),'-o',str(p/'matrix')];subprocess.run(c,env=e,check=True);(p/('matrix-phi16-build.'+arch+'.json')).write_text(json.dumps(c));x=subprocess.check_output(['taskset','-c','52'if arch=='aarch64'else'12',str(p/'matrix')],env=e,text=True);(p/('matrix-phi16.'+arch+'.json')).write_text(x);d=json.loads(x);rs=d['samples'];keys=sorted(set((v['len'],v['kind'],v['equal_slots'])for v in rs));summary=[dict(len=k[0],kind=k[1],equal_slots=k[2],ns={str(m):statistics.median(v['elapsed_ns']/v['reps']for v in rs if(v['len'],v['kind'],v['equal_slots'])==k and v['mode']==m)for m in range(4)})for k in keys];(p/('matrix-phi16-summary.'+arch+'.json')).write_text(json.dumps(summary,indent=2));print('checked',d['checked_pairs'],'pairs;',len(keys),'scenarios')
